const TOMATO_CUTOUT_KEY = 'yara_tomato_cutout_v1';
let tomatoCutoutUrl = '';
function loadTomatoCutout() {
try {
const saved = localStorage.getItem(TOMATO_CUTOUT_KEY);
return typeof saved === 'string' ? saved : '';
} catch (error) {
return '';
}
}
function saveTomatoCutout(value) {
try {
localStorage.setItem(TOMATO_CUTOUT_KEY, value);
} catch (error) {
}
}
function knockoutWhite(source, maxSize = 760, threshold = 232, feather = 26) {
return new Promise(resolve => {
const image = new Image();
image.onload = () => {
try {
const scale = Math.min(1, maxSize / Math.max(image.naturalWidth || maxSize, image.naturalHeight || maxSize));
const width = Math.max(1, Math.round((image.naturalWidth || maxSize) * scale));
const height = Math.max(1, Math.round((image.naturalHeight || maxSize) * scale));
const canvas = document.createElement('canvas');
canvas.width = width;
canvas.height = height;
const context = canvas.getContext('2d');
if (!context) {
resolve('');
return;
}
context.drawImage(image, 0, 0, width, height);
const data = context.getImageData(0, 0, width, height);
const pixels = data.data;
for (let index = 0; index < pixels.length; index += 4) {
const r = pixels[index];
const g = pixels[index + 1];
const b = pixels[index + 2];
const min = Math.min(r, g, b);
const max = Math.max(r, g, b);
const nearWhite = min >= threshold && max - min < 18;
if (nearWhite) {
pixels[index + 3] = 0;
continue;
}
if (min >= threshold - feather) {
const factor = Math.max(0, Math.min(1, (threshold - min) / feather));
pixels[index + 3] = Math.round(pixels[index + 3] * factor);
}
}
context.putImageData(data, 0, 0);
resolve(canvas.toDataURL('image/png'));
} catch (error) {
resolve('');
}
};
image.onerror = () => resolve('');
image.src = source;
});
}
let tomatoCutoutFailed = false;
function ensureTomatoCutout() {
if (tomatoCutoutUrl) return Promise.resolve(tomatoCutoutUrl);
const cached = loadTomatoCutout();
if (cached) {
tomatoCutoutUrl = cached;
return Promise.resolve(cached);
}
if (tomatoCutoutFailed) return Promise.resolve('');
return knockoutWhite(POMODORO_DEFAULT_IMAGE).then(result => {
if (result) {
tomatoCutoutUrl = result;
saveTomatoCutout(result);
} else {
tomatoCutoutFailed = true;
}
return result;
}).catch(() => {
tomatoCutoutFailed = true;
return '';
});
}
function applyTomatoImage() {
const image = getPomodoroImage();
const tomatoImage = $('#pomodoroTomatoImage');
if (!tomatoImage) return;
if (image) {
if (tomatoImage.getAttribute('src') !== image.source) tomatoImage.src = image.source;
tomatoImage.alt = '番茄图';
tomatoImage.classList.add('is-custom');
tomatoImage.hidden = false;
return;
}
tomatoImage.classList.remove('is-custom');
tomatoImage.alt = '两只戴着耳机的卡通番茄';
tomatoImage.hidden = false;
ensureTomatoCutout().then(result => {
if (!result) {
if (!tomatoImage.getAttribute('src')) tomatoImage.src = POMODORO_DEFAULT_IMAGE;
return;
}
if (tomatoImage.getAttribute('src') !== result) tomatoImage.src = result;
}).catch(() => {
if (!tomatoImage.getAttribute('src')) tomatoImage.src = POMODORO_DEFAULT_IMAGE;
});
}
