// 月相页：把写死的占位内容换成按真实日期算出来的值
const PLANETARY_DAYS = ['日曜日', '月曜日', '火曜日', '水曜日', '木曜日', '金曜日', '土曜日'];
const MOON_ILLUMINATION_NOTES = {
新月: '月光几乎藏起来了',
蛾眉月: '月光刚刚探出一点边',
上弦月: '月光正在慢慢变满',
盈凸月: '月光已经丰盈起来',
满月: '月光正满',
亏凸月: '月光开始回落',
下弦月: '月光正在慢慢变亏',
残月: '月光只剩下细细一线'
};
function renderMoonView() {
const now = new Date();
const phase = getMoonPhaseByDate(now);
const age = getMoonAge(now);
const illumination = Math.round((1 - Math.cos((2 * Math.PI * age) / LUNAR_CYCLE)) / 2 * 100);
const name = $('#moonPhaseName');
if (name) name.textContent = phase.name;
const note = $('#moonIllumination');
if (note) note.textContent = `${MOON_ILLUMINATION_NOTES[phase.name] || '月光记录着时间'}（月龄 ${age.toFixed(1)} 天 · 照亮 ${illumination}%）`;
const planet = $('#planetaryDayName');
if (planet) planet.textContent = PLANETARY_DAYS[now.getDay()];
const date = $('#astrologyDate');
if (date) date.textContent = `${now.getMonth() + 1}月${now.getDate()}日`;
}
