// 删内置颜文字要记进删除名单，否则下次启动会被 ensureBuiltinKaomojiCards()
// 当成"缺这条"补回来，用户根本删不掉
const noted = rememberRemovedBuiltinKaomoji(group, card.id);
group.cards = group.cards.filter(item => item.id !== card.id);
