function downloadJson(filename, data) {
const blob = new Blob([JSON.stringify(data, null, 2)], { type: 'application/json' });
const url = URL.createObjectURL(blob);
const link = document.createElement('a');
link.href = url;
link.download = filename;
link.click();
window.setTimeout(() => URL.revokeObjectURL(url), 0);
}
// 备份 / 字卡 / 图片索引这类文件可能带 BOM 或首尾空白，直接 JSON.parse 会炸
function parseJsonLoose(text) {
const raw = String(text ?? '').replace(/^\uFEFF/, '').replace(/^\s+/, '');
if (!raw) throw new Error('文件是空的');
return JSON.parse(raw);
}
function readJsonFile(file) {
return new Promise((resolve, reject) => {
const reader = new FileReader();
reader.onload = () => {
try {
resolve(parseJsonLoose(reader.result));
} catch (error) {
reject(new Error(`invalid-json:${error && error.message ? error.message : 'parse-failed'}`));
}
};
reader.onerror = () => reject(new Error('文件读取失败，可能没有访问权限'));
reader.readAsText(file);
});
}
/* ---- 文件选择 ----
之前所有「导入」都是按钮 click 时调 hiddenInput.click()。
这条链路依赖浏览器的「瞬时用户激活」，在部分手机浏览器 / 内置 WebView 里
会被静默忽略，表现就是点了导入完全没反应、也没任何提示。
现在把 input 直接盖在按钮上：真实点击落在 input 自己身上，不需要任何用户手势；
按钮 click 里的 input.click() 只作为兜底（且已经点中 input 时会跳过，避免弹两次）。 */
function mountFileInput(trigger, input) {
if (!trigger || !input) return;
input.removeAttribute('hidden');
input.classList.add('file-input-overlay');
trigger.classList.add('file-trigger');
if (input.parentElement !== trigger) trigger.appendChild(input);
}
function bindFileTrigger(trigger, input) {
if (!trigger || !input) return;
if (input.dataset.overlayBound === '1') {
mountFileInput(trigger, input);
return;
}
input.dataset.overlayBound = '1';
mountFileInput(trigger, input);
trigger.addEventListener('click', event => {
if (event.target === input) return;
mountFileInput(trigger, input);
input.click();
});
}
function bindFileTriggerById(triggerId, inputId) {
bindFileTrigger(document.getElementById(triggerId), document.getElementById(inputId));
}
// 多个按钮共用同一个 input（头像等）：先把 input 挂到当前按钮上再调用
function clickFileInput(input, trigger) {
if (!input) return;
mountFileInput(trigger, input);
input.click();
}
// 「全部字卡备份」的导出内容。
//
// 显式列出字段，不直接把 cardLibrary 整个序列化 —— 直接倒出去会把
// verbatim、scheduleGroupIds 这些内部兼容标记也带进文件，换个版本再导回来
// 就可能按着错误的标记解析。分组和字卡是配套的，所以两组一起出：
//   group.scope / bindCharIds / role / disabled —— 分类落在哪一列、谁能用、用途、禁用
//   card.text / title / type / usage / disabled    —— 单卡内容、表情类型、禁用
// 少了任何一个，恢复之后都会静默丢信息（专属分类掉回通用列、
// 专属绑定清空、禁用失效），而且不会报错，很难发现。
function buildCardBackupPayload() {
return {
app: 'Yara',
kind: 'card-library',
version: 4,
exportedAt: new Date().toISOString(),
joinMode: Boolean(cardLibrary.joinMode),
// 初始分组被用户删掉的墓碑。漏了它，恢复备份之后这些组会被重新灌一遍
dailyGroupRemoved: Boolean(cardLibrary.dailyGroupRemoved),
removedSeedGroupIds: Array.isArray(cardLibrary.removedSeedGroupIds) ? cardLibrary.removedSeedGroupIds.map(String) : [],
groups: (cardLibrary.groups || []).map(group => ({
id: group.id,
name: group.name,
role: group.role || CARD_GROUP_ROLE_DAILY,
scope: cardGroupScope(group),
builtinKind: group.builtinKind || '',
// 内置颜文字组的灌注水位线和删除名单。少了它们，恢复备份之后
// 用户删掉的内置颜文字会全被补回来
builtinSeededCount: Number.isFinite(Number(group.builtinSeededCount)) ? Number(group.builtinSeededCount) : null,
builtinRemovedIds: Array.isArray(group.builtinRemovedIds) ? group.builtinRemovedIds.map(String) : [],
bindCharIds: (group.bindCharIds || []).map(String),
disabled: normalizeCardDisabled(group.disabled),
cards: (group.cards || []).map(card => ({
id: card.id,
text: card.text,
title: card.title || '',
type: card.type === 'emoji' ? 'emoji' : 'normal',
usage: card.usage || '',
disabled: normalizeCardDisabled(card.disabled)
}))
}))
};
}
async function exportCardLibrary() {
const payload = buildCardBackupPayload();
// 这里必须先算出数字再 toast。原来写成 `groups.reduce(...)`，
// 而 groups 已经是"分组个数"（一个 number）了，reduce 在数字上不存在，
// 直接抛 "groups.reduce is not a function" —— 文件其实已经写出来了，
// 但 toast 没弹、后面那行也不会跑，看起来像完全没导出。
const groups = payload.groups.length;
const cards = payload.groups.reduce((sum, group) => sum + group.cards.length, 0);
const stamp = (() => {
const now = new Date();
const pad = value => String(value).padStart(2, '0');
return `${now.getFullYear()}${pad(now.getMonth() + 1)}${pad(now.getDate())}-${pad(now.getHours())}${pad(now.getMinutes())}`;
})();
// 文件名带时间戳，连着导几次不会互相覆盖，也不会搞不清哪份最新
downloadJson(`全部字卡备份-${stamp}.json`, payload);
showToast(`已导出全部字卡：${groups} 个分组 / ${cards} 张`);
}
async function importCardLibrary(file) {
if (!file) return;
try {
let parsed;
try {
parsed = await readJsonFile(file);
} catch (jsonError) {
// 兜底：很多人直接拿 txt / md 文本文件来导入，按行拆成字卡
const text = await file.text();
const lines = text.replace(/^\uFEFF/, '').split(/\r?\n/).map(line => line.trim()).filter(Boolean);
if (lines.length) {
parsed = { groups: [{ name: file.name.replace(/\.[^.]+$/, '').slice(0, 24) || '导入字卡', cards: lines }] };
showToast('检测到纯文本文件，已按行导入为字卡');
} else {
throw jsonError;
}
}
// 先按「文件里实际带来的」统计，避免把自动补的颜文字 / emoji 算进去
const sourceGroups = readCardGroupsFromUnknown(parsed);
const importedGroups = sourceGroups.filter(group => pickCardList(group).some(entry => readCardTextEntry(entry)));
const importedCards = importedGroups.reduce((sum, group) => sum + pickCardList(group).filter(entry => readCardTextEntry(entry)).length, 0);
// 文件里一个字卡都没解析出来时必须明确报错，
// 否则只是「导入成功」但字卡库看起来毫无变化，等于什么都没发生
if (!importedCards) {
showToast('这个文件里没有识别到任何字卡，请确认是字卡库导出的 json');
return;
}
// 导入：分组、组名、顺序完全跟随文件，一组字卡就是一组，不改名也不补空分组
cardLibrary = normalizeCardLibrary(parsed, { verbatim: true });
activeCardGroupId = '';
// 和启动时走同一条迁移：删掉表情包分组、把颜文字转成内置组、补 scope 默认值。
// 少了这一步，恢复一份旧备份就会把已下架的表情包分类原样带回来
migrateCardLibraryScope();
ensureMoodEmojiCards();
// 和启动时同一套：恢复备份后内置颜文字也得补齐，
// 不然一份不含颜文字的老备份会把内置组清空
ensureBuiltinKaomojiCards();
// 初始日常字卡也要补齐：恢复一份不含它们的老备份不能让「日常」变空
ensureDailyCards();
saveCardLibrary();
renderCardGroups();
// 用归一化之后的结果重新统计，而不是沿用导入前的 importedCards：
// 迁移会删掉表情包分组、会把颜文字组补上，两个数对不上是正常的
const restoredGroups = cardLibrary.groups.length;
const restoredCards = cardLibrary.groups.reduce((sum, group) => sum + (group.cards || []).length, 0);
showToast(`字卡已恢复：${restoredGroups} 个分组 / ${restoredCards} 张`);
} catch (error) {
console.error('[字卡导入失败]', error);
showToast(`字卡导入失败：${String(error && error.message ? error.message : error).replace(/^invalid-json:/, 'JSON 格式错误 ')}`);
}
}
