async function applyBackupPayload(payload, mode) {
// 追加模式下也要认：mergeBackupAppend 会把本地当前数据当基底，
// 拿一个不相干的文件进来同样会污染
if (!isYaraBackupPayload(payload)) {
throw new Error('这不是本应用导出的备份文件（缺少 Yara 备份标识），已取消导入，本地数据未改动');
}
const data = mode === 'appendUpdate' ? mergeBackupAppend(collectBackupPayload(), payload) : payload;
if (mode === 'overwrite') clearAllLocalData();
if (data.profile?.user && data.profile?.dream) {
state = {
user: { name: String(data.profile.user.name || '我').trim().slice(0, 12) || '我', nickname: String(data.profile.user.nickname ?? data.profile.user.name ?? '我').trim().slice(0, 12) || '我', avatar: typeof data.profile.user.avatar === 'string' ? data.profile.user.avatar : '' },
dream: { name: String(data.profile.dream.name || '梦角').trim().slice(0, 12) || '梦角', nickname: String(data.profile.dream.nickname ?? data.profile.dream.name ?? '梦角').trim().slice(0, 12) || '梦角', avatar: typeof data.profile.dream.avatar === 'string' ? data.profile.dream.avatar : '' }
};
persist();
}
if (Array.isArray(data.anniversaries)) anniversaryEntries = data.anniversaries;
if (Array.isArray(data.chat)) chatMessages = data.chat.map(normalizeChatMessage).filter(Boolean).slice(-CHAT_MESSAGE_LIMIT);
if (data.directSessions && Array.isArray(data.directSessions.contacts) && Array.isArray(data.directSessions.sessions)) {
const restoredContacts = data.directSessions.contacts.map(normalizeDirectContact).filter(Boolean);
const restoredSessions = data.directSessions.sessions.map((session, index) => normalizeDirectSession(session, restoredContacts, index)).filter(Boolean);
directData = restoredContacts.some(contact => contact.id === 'dream')
? { contacts: restoredContacts, sessions: restoredSessions }
: loadDirectData(chatMessages);
}
if (data.memos) memoData = normalizeMemoData(data.memos);
if (data.letters) letterData = normalizeLetterData(data.letters);
if (data.surveys) surveyData = normalizeSurveyData(data.surveys);
if (data.schedules) scheduleData = normalizeScheduleData(data.schedules);
if (data.pomodoro) pomodoroData = normalizePomodoroData(data.pomodoro);
// 备份里的字卡库同样带着 verbatim 标记，恢复时要遵守
if (data.cardLibrary) cardLibrary = normalizeCardLibrary(data.cardLibrary, { verbatim: Boolean(data.cardLibrary.verbatim) });
if (data.imageLibrary) imageLibrary = normalizeImageLibrary(data.imageLibrary);
if (data.menstrual) menstrualData = normalizeMenstrualData(data.menstrual);
if (data.moods && typeof data.moods === 'object') dayMoodRecords = data.moods;
if (data.momentConfig) momentConfig = { ...momentConfig, ...data.momentConfig, momentGen: { ...momentConfig.momentGen, ...(data.momentConfig.momentGen || {}) }, commentGen: { ...momentConfig.commentGen, ...(data.momentConfig.commentGen || {}) } };
if (Array.isArray(data.diaryList)) diaryList = data.diaryList;
if (data.diaryConfig) diaryConfig = { ...diaryConfig, ...data.diaryConfig };
if (data.collect && typeof data.collect === 'object') collectData = data.collect;
if (Array.isArray(data.books)) shelfBookList = data.books;
if (data.globalComm) saveGlobalCommConfig(data.globalComm);
if (data.commConfig && typeof data.commConfig === 'object') {
commConfigMap = Object.fromEntries(Object.entries(data.commConfig).map(([id, value]) => [String(id), normalizeCommConfig(value)]));
saveCommConfigMap();
}
if (data.diaryGenRecord && typeof data.diaryGenRecord === 'object') {
diaryGenRecord = data.diaryGenRecord;
saveDiaryAll();
}
if (data.callView && typeof data.callView === 'object') {
callAlwaysOnTop = Boolean(data.callView.alwaysOnTop);
try {
localStorage.setItem(CALL_VIEW_STORAGE_KEY, JSON.stringify(data.callView));
} catch (error) {
/* 忽略写入失败 */
}
}
// 外观与图片资源
if (data.beauty && typeof data.beauty === 'object') {
beautyData = normalizeBeauty(data.beauty);
saveBeauty();
applyBeauty();
}
if (Array.isArray(data.beautyPresets)) {
beautyPresets = data.beautyPresets;
saveBeautyPresets();
}
if (data.albumWidget && typeof data.albumWidget === 'object') {
albumWidget = normalizeAlbumWidget(data.albumWidget);
saveAlbumWidget();
applyCoverWidgetImage();
}
if (data.music && typeof data.music === 'object') {
musicData = normalizeMusicData(data.music);
saveMusicData();
}
if (data.readerSetting) {
shelfReaderSetting = { ...SHELF_READER_DEFAULT, ...data.readerSetting };
saveShelfReaderSetting();
}
if (data.keepAlive) setKeepAlive(data.keepAlive === 'on');
activeDirectSessionId = directData.sessions[0]?.id || '';
chatMessages = getActiveDirectMessages();
activeCardGroupId = '';
activeShelfBookIdSafeReset();
saveAnniversaryEntries();
saveDirectData();
saveChatMessages();
saveCardLibrary();
saveImageLibrary();
saveMemoData();
saveSurveyData();
saveLetterData();
saveScheduleData();
savePomodoroData();
saveMenstrualData();
saveDayMoodRecords();
saveMomentConfig();
saveDiaryAll();
saveCollectData();
saveShelfBooks();
renderAnniversaryList();
renderProfile();
renderChatMessages();
renderCardGroups();
renderImageLibrary();
renderMemoPanel();
renderMusicPage();
renderDiaryHomeList?.();
renderCollectView?.();
renderShelfGrid?.();
// 回传一份「到底进来了什么」的清单，导入成功后直接显示给用户
const summary = [];
const msgCount = directData.sessions.reduce((n, session) => n + (Array.isArray(session?.messages) ? session.messages.length : 0), 0);
if (directData.sessions.length) summary.push(`联系人 ${directData.contacts.length} 位 / 聊天 ${msgCount} 条`);
const cardCount = cardLibrary.groups.reduce((n, group) => n + (Array.isArray(group?.cards) ? group.cards.length : 0), 0);
if (cardCount) summary.push(`字卡 ${cardCount} 张`);
if (imageLibrary.list.length) summary.push(`图片 ${imageLibrary.list.length} 张`);
if (musicData.tracks.length) summary.push(`音乐 ${musicData.tracks.length} 首`);
if (shelfBookList.length) summary.push(`书籍 ${shelfBookList.length} 本`);
if (diaryList.length) summary.push(`日记 ${diaryList.length} 篇`);
if (memoData.notes.length) summary.push(`备忘录 ${memoData.notes.length} 条`);
if (letterData.letters.length) summary.push(`信件 ${letterData.letters.length} 封`);
if (!summary.length) return '导入完成，但这个文件里没有可恢复的内容，即将刷新页面';
return `导入成功：${summary.join('、')}`;
}
