if (!files.length) {
showToast('没有可导入的图片文件');
return;
}
imageBatchFiles = files;
fillImageBatchTargets('');
const totalBytes = files.reduce((sum, file) => sum + file.size, 0);
const gifCount = files.filter(isAnimatedImageType).length;
