targetMode: [SURVEY_TARGET_MODES.ALL, SURVEY_TARGET_MODES.GROUP, SURVEY_TARGET_MODES.SINGLE].includes(value.targetMode) ? value.targetMode : SURVEY_TARGET_MODES.ALL,
targetList: Array.isArray(value.targetList) ? value.targetList.map(id => String(id) === 'me-self' ? SURVEY_SELF_ID : String(id)).filter(Boolean).slice(0, 100) : [],
visibility: value.visibility === 'private' ? 'private' : 'public',
deadline: value.deadline || null,
allowRepeat: Boolean(value.allowRepeat),
anonymous: Boolean(value.anonymous),
resultPerm: [SURVEY_RESULT_PERMISSIONS.SENDER, SURVEY_RESULT_PERMISSIONS.AFTER, SURVEY_RESULT_PERMISSIONS.ALL].includes(value.resultPerm) ? value.resultPerm : SURVEY_RESULT_PERMISSIONS.SENDER,
allowReject: value.allowReject !== false,
