// 拼字卡时补在两张字卡之间的分隔标点
const CARD_JOIN_SEPARATORS = Object.freeze(['，', '。', '、', '；']);
// 注意：这两个正则**不能带 /g**。带 g 的正则做 .test() 会走 lastIndex，
// 同一个正则连着 test 两次结果会时对时错（经典的 lastIndex 陷阱）。
// 现有的 CARD_PUNCTUATION_PATTERN 带 /g，所以这里单独写一份无状态的。
const CARD_TRAILING_PUNCTUATION_PATTERN = /[\p{P}]$/u;
const CARD_LEADING_PUNCTUATION_PATTERN = /^[\p{P}]/u;
// 把**已经挑好的**若干条字卡拼成一段，逐张之间按需补分隔标点。
// 抽条数和拼接是两件事，所以拆开：拼字卡模式自己抽 2~4 条，
// 朋友圈/备忘录/信件/日记 则按用户配置的条数区间抽 —— 两者共用这一段拼接口径，
// 不会出现"聊天里拼接带标点、朋友圈里硬拼"的割裂感。
function joinCardListWithSeparators(list) {
const picked = (list || []).map(text => String(text || '').trim()).filter(Boolean);
if (!picked.length) return '';
if (picked.length < 2) return picked[0];
let result = picked[0];
for (let i = 1; i < picked.length; i += 1) {
const previous = picked[i - 1];
const current = picked[i];
// 下一张开头已经有标点的话也不补，否则「，」+「……好」会连出两个标点
const needSeparator = !CARD_TRAILING_PUNCTUATION_PATTERN.test(previous)
&& !CARD_LEADING_PUNCTUATION_PATTERN.test(current);
const separator = needSeparator
? CARD_JOIN_SEPARATORS[Math.floor(Math.random() * CARD_JOIN_SEPARATORS.length)]
: '';
result += `${separator}${current}`;
}
return result;
}
// 拼字卡模式：把 2~4 张字卡拼成一条消息，而不是只抽一张
function joinCardTexts(pool) {
// 顺手 trim：字卡两端留着空格的话，补出来会是「晚安 ，想你」这种
const list = (pool || []).map(text => String(text || '').trim()).filter(Boolean);
if (list.length < 2) return pickCardText(list);
const wanted = Math.min(list.length, 2 + Math.floor(Math.random() * 3));
const picked = [];
const used = new Set();
while (picked.length < wanted) {
const index = Math.floor(Math.random() * list.length);
if (used.has(index)) break;
used.add(index);
picked.push(list[index]);
}
// 硬拼出来会是「满心都是你只偏爱你」这种读不通的句子，所以两张之间要补分隔标点
return joinCardListWithSeparators(picked);
}
/* ---- 朋友圈 / 备忘录 / 信件 / 日记 共用：按配置抽 N 条字卡并拼成一段 ----
条数在「全局设置的最低/最多」之间随机取，且不会超过池子实际大小 ——
池子只有 2 张时按 1~6 抽，抽出来的也只是那 2 张，不会重复凑数。
拼接走 joinCardTexts 的同一套标点口径：上一张末尾自带标点就不再补。 */
function drawFeatureCards(pool, options = {}) {
const list = (pool || []).map(text => String(text || '').trim()).filter(Boolean);
if (!list.length) return '';
if (options.single) return pickCardText(list);
const global = getGlobalCommConfig();
const minCount = Math.max(1, Number(global.cardReplyMinCount) || 1);
const maxCount = Math.max(minCount, Number(global.cardReplyMaxCount) || minCount);
const wanted = Math.min(list.length, minCount + Math.floor(Math.random() * (maxCount - minCount + 1)));
const picked = [];
const used = new Set();
while (picked.length < wanted) {
const index = Math.floor(Math.random() * list.length);
if (used.has(index)) break;
used.add(index);
picked.push(list[index]);
}
// 单条时不必走拼接（也省掉随机补标点带来的意外）
return joinCardListWithSeparators(picked);
}
// 这四项的"回复时长区间"，同样来自全局设置（四个功能共用一组）
function getFeatureReplyDelayMs() {
const global = getGlobalCommConfig();
const minSec = Math.max(0, Number(global.cardReplyMinSec) || 0);
const maxSec = Math.max(minSec, Number(global.cardReplyMaxSec) || minSec);
return Math.round((minSec + Math.random() * (maxSec - minSec)) * 1000);
}
function buildDreamReplyText(contactId, userText) {
const intent = detectDreamReplyIntent(userText);
const pool = getDreamDialoguePool(contactId);
let text = cardLibrary.joinMode ? joinCardTexts(pool) : pickCardText(pool);
if (!text) text = pickCardText(DREAM_REPLY_POOLS[intent] || DREAM_REPLY_POOLS.default);
if (!text) return '';
// 群聊里 Dream 偶尔会 @ 我（低概率），或 @ 别的梦角（更低概率）
text = `${maybeMentionMePrefix(contactId)}${text}`;
// 颜文字开关打开时，偶尔在句尾缀一个颜文字
if (Math.random() * 100 < 35) {
const mark = pickKaomojiForReply();
if (mark && !text.includes(mark)) text = `${text}${mark}`;
}
return text;
}
/* 取消「正在输入中」那一档的排队。
不带参数＝只取消当前会话（原来只有一个全局 timer，等价于全取消）；
传 '*' ＝全部会话。切换会话时要用前者，不能把别的会话正在排的回复也掐掉。 */
function cancelDreamReply(sessionId = getActiveDirectSession()?.id || '*') {
cancelDreamReplyBurst(sessionId);
if (sessionId === '*') {
dreamReplyTimers.forEach(timerId => window.clearTimeout(timerId));
dreamReplyTimers.clear();
return;
}
const timerId = dreamReplyTimers.get(sessionId);
if (!timerId) return;
window.clearTimeout(timerId);
dreamReplyTimers.delete(sessionId);
}
/* ---- 梦角连着说好几条 ----
一次回复可能是 1~6 条，条数越多概率越低（权重合计 100）：
1条 46% / 2条 24% / 3条 14% / 4条 8% / 5条 5% / 6条 3%
平均约 1.8 条，绝大多数时候还是一条，符合"也可能多条"而不是"总是刷屏"。
三条不能省的约束：
1) 必须一条一条按节奏发。同一帧 append 六条，气泡会同时出现，
看起来不是"连着说"而是界面卡了。
2) 一次连发里不能出现重复内容 —— 池子小的时候连抽两次会抽到同一条，
屏幕上就出现两条一模一样的。
3) 用户在这期间发了新消息就掐掉剩下的。用户都开口了，梦角还自顾自
刷屏比多发两条更烦人。 */
const DREAM_REPLY_BURST_WEIGHTS = Object.freeze([46, 24, 14, 8, 5, 3]);
/* 连发链的 timer 也按会话存。同一个会话同时只允许一条链在跑
（新链开始前掐掉旧链，否则旧链变成孤儿继续刷，实测能堆出 107 条）；
不同会话各跑各的，互不干扰 —— 这正是"每个人都能回复"的关键。 */
const dreamBurstTimers = new Map();
function pickDreamReplyBurstCount() {
let roll = Math.random() * 100;
for (let index = 0; index < DREAM_REPLY_BURST_WEIGHTS.length; index += 1) {
roll -= DREAM_REPLY_BURST_WEIGHTS[index];
if (roll < 0) return index + 1;
}
return 1;
}
/* 不带参数＝取消当前会话的连发链；传 '*'＝全部。
stopChatTyping 只在当前会话上生效，所以只有取消当前会话那条才停输入提示。 */
function cancelDreamReplyBurst(sessionId = '*') {
if (sessionId === '*') {
dreamBurstTimers.forEach(timerId => window.clearTimeout(timerId));
dreamBurstTimers.clear();
stopChatTyping();
return;
}
const timerId = dreamBurstTimers.get(sessionId);
if (timerId) {
window.clearTimeout(timerId);
dreamBurstTimers.delete(sessionId);
if (sessionId === getActiveDirectSession()?.id) stopChatTyping();
}
}
