function resetMusicQueue() {
stopMusicAudio();
musicQueue = getMusicQueue();
musicQueueIndex = musicQueueIndex >= musicQueue.length ? 0 : musicQueueIndex;
musicPlaying = false;
renderPlayerState();
}
function playMusicIndex(index) {
if (!musicQueue.length) {
showToast('播放分组里还没有曲目');
return;
}
if (index < 0) index = musicQueue.length - 1;
if (index >= musicQueue.length) index = 0;
musicQueueIndex = index;
const track = musicQueue[index];
stopMusicAudio();
try {
const audio = new Audio(track.url);
musicAudio = audio;
audio.addEventListener('loadedmetadata', renderPlayerProgress);
audio.addEventListener('durationchange', renderPlayerProgress);
audio.addEventListener('timeupdate', renderPlayerProgress);
audio.addEventListener('pause', renderPlayerProgress);
audio.addEventListener('play', renderPlayerProgress);
audio.addEventListener('ended', () => {
if (musicAudio !== audio) return;
musicPlaying = false;
if (musicShuffle) playMusicIndex(Math.floor(Math.random() * musicQueue.length));
else playMusicIndex(index + 1);
});
audio.play().then(() => {
musicPlaying = true;
renderPlayerState();
}).catch(() => {
musicPlaying = false;
renderPlayerState();
showToast('音频暂时无法播放');
});
} catch (error) {
showToast('音频暂时无法播放');
}
renderPlayerState();
}
function toggleMusicPlayback() {
if (!musicQueue.length) {
musicQueue = getMusicQueue();
musicQueueIndex = 0;
}
if (!musicQueue.length) {
showToast('播放分组里还没有曲目');
return;
}
if (musicAudio && !musicAudio.paused) {
musicAudio.pause();
musicPlaying = false;
renderPlayerState();
return;
}
if (musicAudio) {
musicAudio.play().then(() => {
musicPlaying = true;
renderPlayerState();
}).catch(() => showToast('音频暂时无法播放'));
return;
}
playMusicIndex(musicQueueIndex < 0 || musicQueueIndex >= musicQueue.length ? 0 : musicQueueIndex);
}
function stepMusicTrack(step) {
if (!musicQueue.length) {
musicQueue = getMusicQueue();
musicQueueIndex = 0;
}
if (!musicQueue.length) {
showToast('播放分组里还没有曲目');
return;
}
playMusicIndex((musicQueueIndex + step + musicQueue.length) % musicQueue.length);
}
const MUSIC_FORMAT_EXT = { mp3: 'mp3', m4a: 'm4a', wav: 'wav', ogg: 'ogg', flac: 'flac', aac: 'aac' };
const MUSIC_KNOWN_EXT = [...Object.values(MUSIC_FORMAT_EXT), 'mp4', 'webm', 'weba', 'aif', 'aiff', 'm4b', 'opus'];
function resolveMusicUrl(rawUrl, format = 'auto') {
const value = String(rawUrl || '').trim();
if (!value) return '';
const suffixIndex = value.search(/[?#]/);
const path = suffixIndex > -1 ? value.slice(0, suffixIndex) : value;
const suffix = suffixIndex > -1 ? value.slice(suffixIndex) : '';
const extMatch = path.match(/\.([a-z0-9]{2,5})$/i);
if (extMatch && MUSIC_KNOWN_EXT.includes(extMatch[1].toLowerCase())) return value;
const target = MUSIC_FORMAT_EXT[format];
if (!target) return value;
const nextPath = extMatch ? path.replace(/\.[a-z0-9]{2,5}$/i, `.${target}`) : `${path}.${target}`;
return `${nextPath}${suffix}`;
}
function addMusicTrack(url, format = 'auto') {
const value = resolveMusicUrl(url, format);
if (!value) {
showToast('请粘贴音频链接');
return false;
}
musicData.tracks.push({ id: `tr-${Date.now()}-${Math.random().toString(36).slice(2, 6)}`, name: `曲目 ${musicData.tracks.length + 1}`, url: value, groupId: 'default', sticky: false });
saveMusicData();
resetMusicQueue();
renderMusicPage();
showToast('已添加曲目');
return true;
}
