function startMusicRowLongPress(event, row) {
if (event.button !== undefined && event.button !== 0) return;
if (event.target.closest('button')) return;
const startX = event.clientX;
const startY = event.clientY;
let timer = window.setTimeout(() => {
timer = null;
musicRowDrag = row;
row.classList.add('is-dragging');
$('#musicTrackList')?.classList.add('is-sorting');
if (navigator.vibrate) navigator.vibrate(12);
}, 420);
const cleanup = () => {
if (timer) window.clearTimeout(timer);
timer = null;
window.removeEventListener('pointermove', onMove);
window.removeEventListener('pointerup', onUp);
window.removeEventListener('pointercancel', onUp);
};
const onMove = moveEvent => {
if (!timer) return;
if (Math.abs(moveEvent.clientX - startX) > 8 || Math.abs(moveEvent.clientY - startY) > 8) cleanup();
};
const onUp = () => {
cleanup();
if (musicRowDrag) commitMusicRowDrag();
// 保险：即使 musicRowDrag 已经是 null，也别把 is-sorting 留在页面上。
// 这个类会让整个列表 touch-action:none，留着就再也滑不动了。
else $('#musicTrackList')?.classList.remove('is-sorting');
};
window.addEventListener('pointermove', onMove);
window.addEventListener('pointerup', onUp);
/* pointercancel 必须和 pointerup 走同一条路。
长按 420ms 后列表上已经加了 .is-sorting（也就是 touch-action:none），
这时浏览器接管手势，派发的是 pointercancel 而不是 pointerup。
以前只监听 pointerup，onUp 不执行 → .is-sorting 永久残留 →
整个音乐页再也滑不动，只剩双指缩放还能用（那不受 touch-action 管）。
字卡列表那边的长按早就处理了 pointercancel，音乐这边漏了。 */
window.addEventListener('pointercancel', onUp);
}
function handleMusicRowDragMove(event) {
if (!musicRowDrag) return;
const list = $('#musicTrackList');
if (!list) return;
const target = document.elementFromPoint(event.clientX, event.clientY)?.closest('.music-track-row');
if (!target || target === musicRowDrag || target.parentElement !== list) return;
const rows = [...list.querySelectorAll('.music-track-row')];
const targetIndex = rows.indexOf(target);
const currentIndex = rows.indexOf(musicRowDrag);
if (targetIndex < 0 || currentIndex < 0) return;
if (targetIndex > currentIndex) list.insertBefore(musicRowDrag, target.nextSibling);
else list.insertBefore(musicRowDrag, target);
}
function commitMusicRowDrag() {
const list = $('#musicTrackList');
const row = musicRowDrag;
musicRowDrag = null;
if (!list || !row) return;
row.classList.remove('is-dragging');
list.classList.remove('is-sorting');
const order = [...list.querySelectorAll('.music-track-row')].map(item => item.dataset.trackId);
const pick = id => musicData.tracks.find(track => track.id === id);
const stickyTracks = order.map(pick).filter(track => track?.sticky);
const normalTracks = order.map(pick).filter(track => track && !track.sticky);
const hidden = musicData.tracks.filter(track => !order.includes(track.id));
musicData.tracks = [...stickyTracks, ...normalTracks, ...hidden];
saveMusicData();
resetMusicQueue();
renderMusicPage();
showToast('曲目顺序已更新');
}
