const occupied = isPomodoroOccupied();
// 原来的条件 `occupied && leftSeconds === 0` 永远不成立（leftSeconds 为 0 时已被重置为满格），
// 而且暂停中的会话本来就该能用「开始」续上，所以只按是否正在计时禁用
if (start) start.disabled = running;
