function renderLetterReplyTasks() {
const list = $('#letterReplyTaskList');
if (!list) return;
list.replaceChildren();
const tasks = letterData.replyTasks.slice().sort((a, b) => new Date(a.triggerTime) - new Date(b.triggerTime));
tasks.forEach(task => {
const item = document.createElement('div');
item.className = `letter-task-item${task.done ? ' is-done' : ''}`;
const copy = document.createElement('span');
copy.textContent = `${getLetterContactName(task.replySender)} · ${task.letterType === LETTER_TYPES.PUBLIC ? '公开信回信' : '私人信回信'}`;
const time = document.createElement('span');
time.textContent = `${task.done ? '已完成' : formatLetterTime(task.triggerTime)}`;
item.append(copy, time);
list.appendChild(item);
});
if (!tasks.length) {
const empty = document.createElement('div');
empty.className = 'letter-task-empty';
empty.textContent = '暂无回信任务。';
list.appendChild(empty);
}
const pending = tasks.filter(task => !task.done).length;
const count = $('#letterTaskCount');
if (count) count.textContent = `${pending} 个待处理`;
}
