async function handleLetterAction(action, letterId) {
if (action === 'read') markLetterRead(letterId);
if (action === 'archive') archiveLetter(letterId);
if (action === 'restore') restoreLetter(letterId);
if (action === 'deliver') {
deliverPendingLetter(letterId);
schedulePendingLetterDelivery();
}
if (action === 'cancel-timed') {
cancelPendingLetter(letterId);
return;
}
if (action === 'destroy' || action === 'destroy-archive') {
if (letterData.config.destroyConfirm && !await askConfirm('确认销毁这封信吗？不可恢复', { danger: true, okText: '销毁' })) return;
destroyLetterFrom(action === 'destroy-archive' ? 'archives' : 'letters', letterId);
}
if (action === 'load-draft') {
openLetterWrite(letterId);
return;
}
if (action === 'delete-draft') {
destroyLetterFrom('drafts', letterId);
}
renderLetterPage();
}
function saveLetterSettings() {
const minHour = Number($('#letterReplyMinInput')?.value ?? 3);
const maxHour = Number($('#letterReplyMaxInput')?.value ?? 18);
const publicMax = Number($('#letterPublicMaxInput')?.value ?? 3);
if (minHour > maxHour) {
showToast('回信最小延迟不能大于最大延迟');
return;
}
if (publicMax < 1) {
showToast('公开信最大回信人数至少为 1');
return;
}
letterData.config = normalizeLetterConfig({
globalProb: $('#letterProbabilityInput')?.value,
probUnit: 'percent',
charInterLetter: $('#letterInterInput')?.checked,
enableReply: $('#letterReplyEnableInput')?.checked,
publicCharSelectProb: $('#letterPublicSelectInput')?.value,
replyProbUnit: 'percent',
replyMinHour: minHour,
replyMaxHour: maxHour,
publicMaxReplyCount: publicMax,
allowAnonymous: $('#letterAnonymousInput')?.checked,
allowTimed: $('#letterTimedInput')?.checked,
allowFestival: $('#letterFestivalInput')?.checked,
readReceipt: $('#letterReceiptInput')?.checked,
destroyConfirm: $('#letterDestroyInput')?.checked
});
if (!letterData.config.enableReply) letterData.replyTasks = letterData.replyTasks.filter(task => task.done);
saveLetterData();
renderLetterSettings();
showToast('信件设置已保存');
}
