function tryTriggerCheckPost(contactId) {
const contact = directData.contacts.find(item => item.id === contactId);
if (!contact || contact.isBlocked) return false;
const config = getCommConfig(contactId);
if (!config.enableCheckPost) return false;
if (Math.random() * 100 >= config.checkPostProb) return false;
if (!SurveyService.isCheckPostCooldownOk(contactId)) return false;
// 每日硬上限：同一位梦角一天最多被查岗 7 次。
// 掷骰子的点位有 5 处，光靠概率压不住"聊得热闹时一屏连着弹好几次"。
//
// 注意这里是「先查名额、真弹出来后才计数」两段式，不是查一下就扣。
// 掷骰点位一次互动可能连着摇好几次，如果每次摇中就扣名额，
// 会出现计数从 1 跳到 3 的情况 —— 次数被那些"其实没弹出查岗"的摇法白吃了，
// 用户一天下来实际被查的次数会明显少于 7 次。
if (!hasCheckPostSlot(contactId)) return false;
if (!openCheckPostPopup(contactId)) return false;
consumeCheckPostSlot(contactId);
return true;
}
/* ---- 查岗每日次数硬上限 ----
和 CALL_DAILY_LIMIT 同一套机制：按「自然日 + 梦角」两个维度存，
占用后立刻落盘（不落盘的话"当天还没被查过"时刷新页面计数仍是空的，
反复刷新就能把上限一直卡在 0）。隔天自动清零。 */
const CHECKPOST_DAILY_LIMIT = 7;
const CHECKPOST_QUOTA_STORAGE_KEY = 'yara_checkpost_daily_quota_v1';
let checkPostQuota = { date: '', counts: {} };
function checkPostQuotaTodayKey() {
const now = new Date();
return `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}-${String(now.getDate()).padStart(2, '0')}`;
}
function checkPostCountToday(contactId) {
const key = checkPostQuotaTodayKey();
if (checkPostQuota.date !== key) checkPostQuota = { date: key, counts: {} };
return Number(checkPostQuota.counts[contactId]) || 0;
}
function hasCheckPostSlot(contactId) {
if (!contactId) return false;
return checkPostCountToday(contactId) < CHECKPOST_DAILY_LIMIT;
}
function consumeCheckPostSlot(contactId) {
if (!contactId) return false;
const used = checkPostCountToday(contactId);
if (used >= CHECKPOST_DAILY_LIMIT) return false;
checkPostQuota.counts[contactId] = used + 1;
try { localStorage.setItem(CHECKPOST_QUOTA_STORAGE_KEY, JSON.stringify(checkPostQuota)); } catch (error) { /* 忽略 */ }
return true;
}
function loadCheckPostQuota() {
try {
const saved = JSON.parse(localStorage.getItem(CHECKPOST_QUOTA_STORAGE_KEY));
if (saved && saved.date === checkPostQuotaTodayKey() && saved.counts && typeof saved.counts === 'object') {
checkPostQuota = { date: saved.date, counts: { ...saved.counts } };
return;
}
checkPostQuota = { date: checkPostQuotaTodayKey(), counts: {} };
} catch (error) {
checkPostQuota = { date: checkPostQuotaTodayKey(), counts: {} };
}
try { localStorage.setItem(CHECKPOST_QUOTA_STORAGE_KEY, JSON.stringify(checkPostQuota)); } catch (error) { /* 忽略 */ }
}
/* ---------------- 通话模块 ---------------- */
let activeCall = null;
