const members = getGroupCallCandidates().filter(item => isCallEnabled(item.id));
if (!members.length) return false;
const caller = members[Math.floor(Math.random() * members.length)];
if (Math.random() * 100 >= getCommConfig(caller.id).callIncomingProb) return false;
// 每日硬上限：先占名额再拨号，占不到就直接放弃
if (!reserveCallSlot(caller.id)) return false;
