function createSurveyBadge(text, className) {
const badge = document.createElement('span');
badge.className = `survey-badge ${className}`;
badge.textContent = text;
return badge;
}
function getSurveyAnswerStatusText(survey) {
if (isSurveyExpired(survey)) return '已过期';
const status = getSurveyStatusMap(survey)[SURVEY_SELF_ID];
// 既答过又拒绝过是允许的状态，两个都要说出来，不能只报一个
if (status?.answered && status?.rejected) return '已作答（另记拒绝）';
if (status?.answered) return '已作答';
if (status?.rejected) return '已拒绝';
return '待作答';
}
function renderSurveyList() {
const list = $('#surveyList');
if (!list) return;
const keyword = ($('#surveySearchInput')?.value || '').trim().toLowerCase();
const tag = $('#surveyTagFilter')?.value || '';
const surveys = surveyData.surveys.filter(survey => {
// 「已归档」是一个独立筛选；否则归档后这份问卷就再也找不回来了
if (tag === 'archived') {
if (!survey.archived) return false;
} else if (survey.archived) {
return false;
}
if (tag && tag !== 'archived' && survey.tag !== tag) return false;
if (!keyword) return true;
return survey.title.toLowerCase().includes(keyword);
}).sort((a, b) => new Date(b.updatedAt || b.createdAt).getTime() - new Date(a.updatedAt || a.createdAt).getTime());
list.replaceChildren();
if (!surveys.length) {
const empty = document.createElement('div');
empty.className = 'survey-list-empty';
empty.textContent = keyword || tag ? '没有找到符合条件的问卷' : '还没有问卷，点击“创建问卷”开始。';
list.appendChild(empty);
return;
}
surveys.forEach(survey => {
const item = document.createElement('article');
item.className = 'survey-item';
const head = document.createElement('div');
head.className = 'survey-item-head';
const copy = document.createElement('div');
const title = document.createElement('strong');
title.className = 'survey-item-title';
title.textContent = survey.title;
const meta = document.createElement('div');
meta.className = 'survey-item-meta';
meta.textContent = `发起者：${getSurveyContactName(survey.senderId)} · ${survey.answers.length} 份作答 · ${getSurveyAnswerStatusText(survey)}`;
copy.append(title, meta);
const badges = document.createElement('div');
badges.className = 'survey-badges';
badges.append(createSurveyBadge(survey.tag === SURVEY_TAGS.CHECKPOST ? '查岗' : survey.tag === SURVEY_TAGS.VOTE ? '投票' : '普通', `survey-badge-${survey.tag}`));
if (survey.targetMode === SURVEY_TARGET_MODES.SINGLE) badges.append(createSurveyBadge('定向', 'survey-badge-private'));
if (survey.targetMode === SURVEY_TARGET_MODES.GROUP) badges.append(createSurveyBadge('指定', 'survey-badge-private'));
if (survey.visibility === 'private') badges.append(createSurveyBadge('私密', 'survey-badge-private'));
if (isSurveyExpired(survey)) badges.append(createSurveyBadge('过期', 'survey-badge-expired'));
head.append(copy, badges);
const actions = document.createElement('div');
actions.className = 'survey-item-actions';
const addAction = (action, text, className = '') => {
const button = document.createElement('button');
button.type = 'button';
button.dataset.surveyAction = action;
button.dataset.surveyId = survey.id;
button.textContent = text;
if (className) button.className = className;
actions.appendChild(button);
};
addAction('answer', '开始作答');
addAction('result', '查看结果');
if (survey.senderId === SURVEY_SELF_ID) addAction('edit', '编辑');
addAction('template', '存为模板');
addAction(survey.archived ? 'unarchive' : 'archive', survey.archived ? '恢复' : '归档');
addAction('delete', '删除', 'survey-delete');
item.append(head, actions);
list.appendChild(item);
});
}
