const usePicked = document.createElement('button');
usePicked.type = 'button';
usePicked.className = 'survey-template-use-picked';
usePicked.addEventListener('click', () => useSelectedSurveyQuestions(template, surveyPickedIndexes(template.id)));
const clearPicked = document.createElement('button');
clearPicked.type = 'button';
clearPicked.className = 'survey-template-clear-picked';
clearPicked.textContent = '清空选择';
clearPicked.addEventListener('click', () => clearSurveyQuestionPicked(template));
pickBar.append(pickCount, usePicked, clearPicked);
