async function deleteDirectContact(contactId) {
const contact = getDirectContact(contactId);
if (!contact || contact.id === 'dream') {
showToast('主梦角联系人不能删除');
return;
}
if (!await askConfirm(`确定删除联系人“${contactLabel(contact)}”吗？`, { danger: true, okText: '删除' })) return;
directData.contacts = directData.contacts.filter(item => item.id !== contactId);
directData.sessions = directData.sessions.filter(session => session.contactId !== contactId);
surveyData.surveys.forEach(survey => {
survey.targetList = (survey.targetList || []).filter(id => id !== contactId);
survey.answers = (survey.answers || []).filter(answer => answer.contactId !== contactId);
});
saveSurveyData();
directData.sessions.forEach(session => {
if (Array.isArray(session.memberIds)) session.memberIds = session.memberIds.filter(id => id !== contactId);
});
// 这个梦角的专属铃声也要一起清掉。原来只清了 surveys / sessions /
// memberIds，charRingAudio 和 charRingNames 里的条目留着，
// Audio 对象和它的 blob URL 就一直占着内存不放。
const removedRing = charRingAudio.get(contactId);
if (removedRing) {
try { if (removedRing.src) URL.revokeObjectURL(removedRing.src); } catch (error) { /* 忽略 */ }
charRingAudio.delete(contactId);
}
if (charRingNames[contactId]) {
const nextRingNames = { ...charRingNames };
delete nextRingNames[contactId];
charRingNames = nextRingNames;
}
if (!directData.sessions.length) directData.sessions = createDefaultDirectData([]).sessions;
if (!directData.sessions.some(session => session.id === activeDirectSessionId)) {
activeDirectSessionId = directData.sessions[0].id;
chatMessages = directData.sessions[0].messages.slice();
}
saveDirectData();
renderContacts();
renderDirectSessions();
renderQuestionnairePage();
if (currentPage === 'chat') renderChatMessages();
showToast('联系人已删除');
}
