function saveAnniversary(event) {
event.preventDefault();
const title = $('#anniversaryTitle').value.trim();
const date = $('#anniversaryDate').value;
if (!title || !date) {
showToast('请填写标题和日期');
return;
}
const entry = {
id: editingAnniversaryId || `anniversary-${Date.now()}`,
type: $('#anniversaryType').value,
title: title.slice(0, 30),
date,
content: $('#anniversaryContent').value.trim().slice(0, 100)
};
const index = anniversaryEntries.findIndex(item => item.id === entry.id);
if (index >= 0) anniversaryEntries[index] = entry;
else anniversaryEntries.push(entry);
saveAnniversaryEntries();
renderAnniversaryList();
closeAnniversaryEditor();
showToast(index >= 0 ? '纪念日记录已更新' : '纪念日记录已添加');
}
// 只在页面初始化或用户操作后刷新，避免界面自行跳动。
