const count = Math.max(1, images.length);
layer.style.backgroundColor = base;
layer.style.backgroundImage = images.length ? images.join(', ') : 'none';
// 固定铺满：cover + no-repeat + fixed，滚页面时背景不动，也不会出现接缝
layer.style.backgroundSize = images.length ? new Array(count).fill('cover').join(', ') : 'auto';
layer.style.backgroundRepeat = images.length ? new Array(count).fill('no-repeat').join(', ') : 'no-repeat';
layer.style.backgroundAttachment = 'fixed';
