// 一旦这里给个半透明，底下 .phone-screen 的内容就会透上来，
// 表现就是「选了纯色却铺不满、隐约还有花纹」—— 这就是原来那个 bug。
layer.style.opacity = '1';
layer.classList.toggle('is-flat', flat);
// 背景只认这个图层：把 .phone-screen 自带的那层内置 background-image 关掉，
// 否则任何「没盖严」的地方都会漏出内置图。
const screen = $('.phone-screen');
if (screen) {
screen.style.backgroundColor = base;
screen.style.backgroundImage = 'none';
}
