if (bg.blur > 0 && !flat) filters.push(`blur(${bg.blur}px)`);
layer.style.filter = filters.length ? filters.join(' ') : 'none';
layer.style.transform = filters.length ? `scale(${1 + bg.blur / 45})` : 'none';
