async function handleDiaryOps(event) {
const button = event.target.closest('button[data-op]');
if (!button) return;
const op = button.dataset.op;
const diaryId = String(button.dataset.diaryId || '');
const diary = diaryList.find(item => item.diaryId === diaryId);
if (op === 'delDiary') {
if (!diary) return;
if (!await askConfirm('确定删除该日记？将同步删除全部下方批注。', { danger: true, okText: '删除' })) return;
diaryList = diaryList.filter(item => item.diaryId !== diaryId);
saveDiaryAll();
renderDiaryHomeList();
showToast('日记已删除');
return;
}
if (op === 'submitTimelineComment') {
if (!diary) return;
const input = $(`#diaryTimelineWrap .diary-comment-input[data-diary-id="${diaryId}"]`);
const text = String(input?.value || '').trim();
if (!text) {
showToast('先写下你的批注');
return;
}
if (!Array.isArray(diary.comments)) diary.comments = [];
diary.comments.push({ commentId: diaryCreateId(), authorType: 'user', dreamId: null, content: text, createTime: Date.now() });
saveDiaryAll();
renderDiaryTimeline();
showToast('批注已提交');
}
}
/* ===== 书架（导入书籍 / 长按段落互相批注） ===== */
