/* ===== zip 解析（不依赖外部库） ===== */
async function inflateZipEntry(bytes, method) {
if (method === 0) return bytes;
if (method !== 8) throw new Error('unsupported');
if (typeof DecompressionStream === 'undefined') throw new Error('no-deflate');
const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate-raw'));
return new Uint8Array(await new Response(stream).arrayBuffer());
}
/* ---- 文件名的自然序（natural order）----
zip 里一章一个 txt 文件时，要按"第 1 章 → 第 2 章 → ……"拼起来。
直接 localeCompare 比字符串会排出 第1章 → 第10章 → 第2章 这种顺序，
因为 '1' 和 '1' 相同后，下一位 '0' < '2'，10 就跑到了 2 前面 ——
拼出来的书章节自然就乱了。中文数字（第二章）同样要能排对。 */
const SHELF_CN_DIGITS = Object.freeze({ 零: 0, 〇: 0, 一: 1, 二: 2, 两: 2, 三: 3, 四: 4, 五: 5, 六: 6, 七: 7, 八: 8, 九: 9 });
/* 中文数字转数值，够章节号用（支持到"万"） */
function shelfCnToNumber(str) {
let total = 0;
let section = 0;
let digit = 0;
for (const ch of String(str || '')) {
if (ch in SHELF_CN_DIGITS) {
digit = SHELF_CN_DIGITS[ch];
} else if (ch === '十') {
section += (digit || 1) * 10;
digit = 0;
} else if (ch === '百') {
section += (digit || 1) * 100;
digit = 0;
} else if (ch === '千') {
section += (digit || 1) * 1000;
digit = 0;
} else if (ch === '万') {
total += (section + digit) * 10000;
section = 0;
digit = 0;
}
}
return total + section + digit;
}
/* 把路径拆成一串排序键：数字段记 {t:'n',v:数值}，其余记 {t:'s',v:文本}。
逐段比较：先看类型（数字段在前），同类型再比值。 */
function shelfNaturalKey(path) {
const text = String(path || '').toLowerCase();
const keys = [];
const numberReg = /[0-9零〇一二两三四五六七八九十百千万]+/g;
let last = 0;
let match = numberReg.exec(text);
while (match !== null) {
if (match.index > last) keys.push({ t: 's', v: text.slice(last, match.index) });
const raw = match[0];
keys.push({ t: 'n', v: /^[0-9]+$/.test(raw) ? Number(raw) : shelfCnToNumber(raw) });
last = match.index + raw.length;
match = numberReg.exec(text);
}
if (last < text.length) keys.push({ t: 's', v: text.slice(last) });
return keys;
}
function compareShelfPath(a, b) {
const ka = shelfNaturalKey(a);
const kb = shelfNaturalKey(b);
const len = Math.max(ka.length, kb.length);
for (let i = 0; i < len; i += 1) {
const sa = ka[i];
const sb = kb[i];
if (!sa && !sb) return 0;
if (!sa) return -1;
if (!sb) return 1;
if (sa.t !== sb.t) return sa.t === 'n' ? -1 : 1;
if (sa.v !== sb.v) return sa.v < sb.v ? -1 : 1;
}
return String(a).localeCompare(String(b));
}
function decodeZipText(bytes) {
if (bytes[0] === 0xef && bytes[1] === 0xbb && bytes[2] === 0xbf) {
return new TextDecoder('utf-8').decode(bytes.subarray(3));
}
try {
return new TextDecoder('utf-8', { fatal: true }).decode(bytes);
} catch (error) {
try {
return new TextDecoder('gbk').decode(bytes);
} catch (error2) {
return new TextDecoder('utf-8').decode(bytes);
}
}
}
async function readShelfZip(file) {
const buffer = new Uint8Array(await file.arrayBuffer());
const view = new DataView(buffer.buffer);
let eocd = -1;
for (let i = buffer.length - 22; i >= Math.max(0, buffer.length - 66000); i -= 1) {
if (view.getUint32(i, true) === 0x06054b50) {
eocd = i;
break;
}
}
if (eocd < 0) throw new Error('不是有效的 zip 文件');
const count = view.getUint16(eocd + 10, true);
let offset = view.getUint32(eocd + 16, true);
const decoder = new TextDecoder('utf-8');
const texts = [];
for (let index = 0; index < count; index += 1) {
if (view.getUint32(offset, true) !== 0x02014b50) break;
const method = view.getUint16(offset + 10, true);
const compressedSize = view.getUint32(offset + 20, true);
const nameLength = view.getUint16(offset + 28, true);
const extraLength = view.getUint16(offset + 30, true);
const commentLength = view.getUint16(offset + 32, true);
const localOffset = view.getUint32(offset + 42, true);
const name = decoder.decode(buffer.subarray(offset + 46, offset + 46 + nameLength));
offset += 46 + nameLength + extraLength + commentLength;
if (name.startsWith('__MACOSX/')) continue;
const base = name.split('/').pop() || '';
if (!base || base.startsWith('.')) continue;
const lower = base.toLowerCase();
if (!lower.endsWith('.txt') && !lower.endsWith('.md')) continue;
if (view.getUint32(localOffset, true) !== 0x04034b50) continue;
const localNameLength = view.getUint16(localOffset + 26, true);
const localExtraLength = view.getUint16(localOffset + 28, true);
const dataStart = localOffset + 30 + localNameLength + localExtraLength;
const data = buffer.subarray(dataStart, dataStart + compressedSize);
try {
const inflated = await inflateZipEntry(data, method);
texts.push({ path: name, text: decodeZipText(inflated) });
} catch (error) {
/* 跳过无法解压的条目 */
}
}
if (!texts.length) throw new Error('压缩包内未找到 txt / md 文本文件');
texts.sort((a, b) => compareShelfPath(a.path, b.path));
return texts.map(item => item.text).join('\n\n');
}
/* 章节解析：仅识别「第X章」，空行分段，硬换行自动合并 */
function parseShelfBookText(rawText) {
let text = String(rawText || '')
.replace(/[\u200B-\u200D\uFEFF]/g, '')
.replace(/\r\n/g, '\n')
.replace(/\r/g, '\n')
.replace(/\n{3,}/g, '\n\n');
const chapterReg = /^(\s*)(第[0-9一二三四五六七八九十百千万零]+章)(.*)$/gm;
const parts = [];
let lastIndex = 0;
let match = chapterReg.exec(text);
while (match !== null) {
if (match.index > lastIndex) parts.push({ type: 'text', content: text.slice(lastIndex, match.index) });
parts.push({ type: 'chapter', title: match[2] });
lastIndex = match.index + match[0].length;
match = chapterReg.exec(text);
}
if (lastIndex < text.length) parts.push({ type: 'text', content: text.slice(lastIndex) });
const chapters = [];
let current = null;
parts.forEach(part => {
if (part.type === 'chapter') {
if (current) chapters.push(current);
current = { cid: shelfCreateId('c'), title: part.title, paragraphs: [] };
return;
}
if (!current) current = { cid: shelfCreateId('c'), title: '全书', paragraphs: [] };
String(part.content || '')
.split(/\n\n/)
.forEach(raw => {
const trimmed = raw.trim();
if (!trimmed) return;
current.paragraphs.push(trimmed.replace(/\n/g, ''));
});
});
if (current) chapters.push(current);
if (!chapters.length) chapters.push({ cid: shelfCreateId('c'), title: '全书', paragraphs: [String(rawText || '').trim()].filter(Boolean) });
return chapters;
}
async function importShelfZip(file) {
if (!file) return;
if (!/\.zip$/i.test(file.name || '')) {
showToast('请选择 zip 压缩包');
return;
}
showToast('正在解析压缩包，请稍候…');
try {
const raw = await readShelfZip(file);
const chapters = parseShelfBookText(raw);
const name = String(file.name || '').replace(/\.zip$/i, '').slice(0, 40) || '未命名书籍';
shelfBookList.push({
bookId: shelfCreateId('b'),
bookName: name,
bookDesc: `共 ${chapters.length} 章`,
cover: '',
importTime: Date.now(),
source: 'zip_package',
annoSetting: { enableUserDreamAnnoInteract: true, dreamAnnoProb: 30 },
chapters,
toc: chapters.map(chapter => ({ cid: chapter.cid, title: chapter.title })),
paragraphs: chapters.flatMap(chapter => chapter.paragraphs),
annoData: {}
});
saveShelfBooks();
closeShelfImportSheet();
renderShelfGrid();
showToast(`已导入《${name.slice(0, 12)}》✦`);
} catch (error) {
showToast(error?.message === '不是有效的 zip 文件' ? '这个文件不是有效的 zip 压缩包' : '压缩包里没有找到 txt / md 文本文件');
}
}
