function optimizeAvatar(file) {
return new Promise((resolve, reject) => {
const reader = new FileReader();
reader.onerror = () => reject(new Error('read-failed'));
reader.onload = () => {
const image = new Image();
image.onerror = () => reject(new Error('decode-failed'));
image.onload = () => {
const maxSize = 360;
const scale = Math.min(1, maxSize / Math.max(image.naturalWidth, image.naturalHeight));
const width = Math.max(1, Math.round(image.naturalWidth * scale));
const height = Math.max(1, Math.round(image.naturalHeight * scale));
const canvas = document.createElement('canvas');
canvas.width = width;
canvas.height = height;
const context = canvas.getContext('2d');
context.fillStyle = '#ffffff';
context.fillRect(0, 0, width, height);
context.drawImage(image, 0, 0, width, height);
resolve(canvas.toDataURL('image/jpeg', .86));
};
image.src = reader.result;
};
reader.readAsDataURL(file);
});
}
async function handleAvatarFile(file) {
if (!file) return;
if (!file.type.startsWith('image/')) {
showToast('请选择图片格式的头像');
return;
}
if (file.size > 8 * 1024 * 1024) {
showToast('请选择 8MB 以内的图片');
return;
}
try {
const source = await optimizeAvatar(file);
draftProfile[uploadTarget] = source;
if (String(uploadTarget).startsWith('contact:')) {
const contactId = String(uploadTarget).slice(8);
const contact = directData.contacts.find(item => item.id === contactId);
if (contact) contact.avatar = source;
const row = $(`#dreamProfileList [data-dream-name="${contactId}"]`)?.closest('.editor-profile');
const image = row?.querySelector('.editor-avatar-preview img');
if (image) {
image.src = source;
image.hidden = false;
}
} else {
setImage(uploadTarget === 'user' ? '#userAvatarPreview' : '#dreamAvatarPreview', source);
}
showToast('头像已准备好，记得保存');
} catch (error) {
showToast('这张图片暂时无法读取，请换一张试试');
}
}
