function renderCalendar() {
const grid = $('#calendarGrid');
if (!grid) return;
const now = new Date();
const year = calendarCursor.getFullYear();
const month = calendarCursor.getMonth();
const firstWeekday = new Date(year, month, 1).getDay();
const daysInMonth = new Date(year, month + 1, 0).getDate();
const monthTitle = $('#calendarMonthTitle');
if (monthTitle) monthTitle.textContent = `${year}年${month + 1}月`;
const cells = [];
const weekdayLabels = [
['周日', '日曜日'],
['周一', '月曜日'],
['周二', '火曜日'],
['周三', '水曜日'],
['周四', '木曜日'],
['周五', '金曜日'],
['周六', '土曜日']
];
weekdayLabels.forEach(([label, japaneseLabel]) => {
const header = document.createElement('div');
header.className = 'calendar-cell calendar-weekday';
header.setAttribute('role', 'columnheader');
header.innerHTML = `<span class="weekday-cn">${label}</span><strong class="weekday-jp">${japaneseLabel}</strong>`;
cells.push(header);
});
// 格子数要按「月初星期 + 当月天数」向上取整到整周，
// 固定 35 格会漏掉最后 1~2 天（例如 2027 年 1 月 31 日永远不显示）
const cellCount = Math.ceil((firstWeekday + daysInMonth) / 7) * 7;
for (let index = 0; index < cellCount; index += 1) {
const date = new Date(year, month, index - firstWeekday + 1);
const inCurrentMonth = date.getMonth() === month;
const isToday = inCurrentMonth && date.toDateString() === now.toDateString();
const isWeekend = date.getDay() === 0 || date.getDay() === 6;
const cell = document.createElement('div');
const phase = getMoonPhaseByDate(date);
cell.className = `calendar-cell calendar-day${inCurrentMonth ? '' : ' muted'}${isToday ? ' today' : ''}${isWeekend ? ' weekend' : ''}`;
cell.setAttribute('aria-label', `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日，${phase.name}`);
cell.title = `${date.getFullYear()}年${date.getMonth() + 1}月${date.getDate()}日｜${phase.name}`;
cell.innerHTML = `<span class="calendar-date">${date.getDate()}</span><span class="calendar-moon-wrap"><span class="calendar-moon">${phase.icon}</span><span class="calendar-phase-label">${phase.name}</span></span>`;
cell.setAttribute('role', 'button');
cell.tabIndex = 0;
cell.addEventListener('click', () => openCalendarDay(date));
cell.addEventListener('keydown', event => {
if (event.key === 'Enter' || event.key === ' ') {
event.preventDefault();
openCalendarDay(date);
}
});
cells.push(cell);
}
grid.replaceChildren(...cells);
}
