$('#surveyCopyResult').addEventListener('click', async () => {
const survey = surveyData.surveys.find(item => item.id === surveyResultId);
if (!survey) return;
const text = getSurveyResultText(survey);
try {
await navigator.clipboard.writeText(text);
} catch (error) {
const helper = document.createElement('textarea');
helper.value = text;
document.body.appendChild(helper);
helper.select();
document.execCommand('copy');
helper.remove();
}
showToast('结果已复制');
});
