const appContent = $('#appContent');
let swipeStartX = 0;
let swipeStartY = 0;
let swipeActive = false;
const finishSwipe = event => {
if (!swipeActive) return;
const deltaX = event.clientX - swipeStartX;
const deltaY = event.clientY - swipeStartY;
swipeActive = false;
if (Math.abs(deltaX) < 48 || Math.abs(deltaX) < Math.abs(deltaY) * 1.2) return;
/* 全站约定是"左滑 = 退出"（浮层那边也是 dx <= -72 就关）。
原来这里写的是 pages=['blank']，currentPage 是任何次级界面时
index === -1 直接 return，等于这个手势从来没生效过。
现在：次级界面左滑 → 回上一页（栈空则回首页）；首页左滑 → 无事发生。
右滑保持原来的"往前一层"语义。 */
if (deltaX < 0) {
if (currentPage === 'blank') return;
const prev = viewHistory[viewHistory.length - 1];
setView(prev || 'blank', { fromHistory: true });
return;
}
if (viewHistory.length) setView(viewHistory[viewHistory.length - 1], { fromHistory: true });
};
appContent.addEventListener('pointerdown', event => {
if (event.pointerType === 'mouse' && event.button !== 0) return;
swipeStartX = event.clientX;
swipeStartY = event.clientY;
swipeActive = true;
});
appContent.addEventListener('pointerup', finishSwipe);
appContent.addEventListener('pointercancel', () => { swipeActive = false; });
