/* ---- 禁止缩放：iOS Safari 会忽略 user-scalable=no，必须用事件兜底 ---- */
function lockViewportZoom() {
// Safari 的双指缩放手势
['gesturestart', 'gesturechange', 'gestureend'].forEach(type => {
document.addEventListener(type, event => event.preventDefault(), { passive: false });
});
// 桌面端 Ctrl / Cmd + 滚轮缩放
document.addEventListener('wheel', event => {
if (event.ctrlKey || event.metaKey) event.preventDefault();
}, { passive: false });
// 双击缩放：两次 touchend 间隔小于 300ms 时吃掉第二次
let lastTouchEnd = 0;
document.addEventListener('touchend', event => {
const now = Date.now();
if (now - lastTouchEnd <= 300) event.preventDefault();
lastTouchEnd = now;
}, { passive: false });
// iOS 长按选中文字时会弹放大镜，两次 touch 也可能连成一串
document.addEventListener('selectstart', event => {
const node = event.target;
if (node instanceof HTMLElement && (node.closest('input, textarea, [contenteditable=""], .shelf-paragraph'))) return;
event.preventDefault();
});
// 兜底：万一上面被绕过，把视口缩放强行按回 1
const reset = () => {
const meta = document.querySelector('meta[name="viewport"]');
if (!meta) return;
const content = meta.getAttribute('content') || '';
if (!/maximum-scale=1/.test(content)) {
meta.setAttribute('content', `${content}, maximum-scale=1, minimum-scale=1, user-scalable=no`);
}
};
reset();
window.addEventListener('orientationchange', () => window.setTimeout(reset, 120));
window.addEventListener('pageshow', reset);
/* 软键盘弹出时可视视口会变矮（iOS 上还会顺带重新计算缩放），
这里盯住 visualViewport.scale：只要不是 1 就按回去，
并把横向滚动位置摆正，避免键盘把界面顶得偏移。 */
const viewport = window.visualViewport;
if (viewport && typeof viewport.addEventListener === 'function') {
let rafId = 0;
viewport.addEventListener('resize', () => {
if (rafId) return;
rafId = window.requestAnimationFrame(() => {
rafId = 0;
if (viewport.scale && Math.abs(viewport.scale - 1) > 0.01) {
window.scrollTo(viewport.offsetLeft, viewport.offsetTop);
reset();
}
});
});
}
/* 最后一道保险：任何可敲字的控件在聚焦瞬间计算字号都必须 >= 16px，
否则 iOS 会当成无障碍需求把整页放大。
CSS 里已经用 !important 兜住了，这里再查一次是为了防止
后续某个模块用内联样式把它改回小字号。 */
const TEXT_ENTRY = 'input:not([type="checkbox"]):not([type="radio"]):not([type="range"]):not([type="color"]):not([type="file"]):not([type="submit"]):not([type="button"]):not([type="image"]), textarea, select';
const enforceFontFloor = event => {
const node = event.target;
if (!(node instanceof HTMLElement) || !node.matches(TEXT_ENTRY)) return;
const size = Number.parseFloat(window.getComputedStyle(node).fontSize);
if (size >= 16) return;
node.style.setProperty('font-size', '16px', 'important');
};
document.addEventListener('focusin', enforceFontFloor);
document.addEventListener('pointerdown', enforceFontFloor, true);
}
