const gotoShelfChapter = delta => {
const book = shelfBook(shelfCurrentBookId);
const chapters = Array.isArray(book?.chapters) ? book.chapters : [];
if (chapters.length < 2) return;
const index = chapters.findIndex(chapter => String(chapter?.cid || '') === shelfCurrentCid);
const next = chapters[(index < 0 ? 0 : index) + delta];
if (!next) return;
shelfCurrentCid = String(next.cid);
renderShelfToc(book);
renderShelfReadContent(book);
const scroll = $('#shelfReadScroll');
if (scroll) scroll.scrollTop = 0;
updateShelfReaderProgress();
};
$('#shelfPrevChapter')?.addEventListener('click', () => gotoShelfChapter(-1));
$('#shelfNextChapter')?.addEventListener('click', () => gotoShelfChapter(1));
